"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9292],{36345:e=>{e.exports=JSON.parse('{"functions":[{"name":"ScaleTween","desc":"Scales `model` from `startScale` to `targetScale` and returns the [RBXScriptConnection]\\ndriving it \u2014 disconnect it to stop the tween early, leaving the model at whatever\\nscale it reached.\\n\\nDefaults to a 0.5s bounce-out from 0.1 to 1, the \\"pop in\\" used when props are\\nplaced. Passing a `tweenInfo` overrides the duration, easing style and direction;\\nits other fields are ignored, so repeat counts and reverses do not apply.\\n\\nThe tween also stops on its own if the model is unparented mid-flight, and snaps\\nto the exact target on completion so rounding never leaves the model slightly off.\\n\\n```lua\\nlocal connection = ScaleTween(prop)\\n```","params":[{"name":"model","desc":"Model to scale","lua_type":"Model"},{"name":"startScale","desc":"Starting scale (defaults to 0.1)","lua_type":"number?"},{"name":"targetScale","desc":"Target scale (defaults to 1)","lua_type":"number?"},{"name":"tweenInfo","desc":"Custom duration and easing instead of the default","lua_type":"TweenInfo?"}],"returns":[{"desc":"Disconnect to stop early","lua_type":"RBXScriptConnection"}],"function_type":"static","source":{"line":58,"path":"src/Shared/Class/ScaleTween.luau"}}],"properties":[],"types":[],"name":"ScaleTween","desc":"Author: dig1t\\n\\nA simple tween that scales a model from a starting scale to a target scale over a\\nset duration.\\n\\n[Model:ScaleTo] is not a property, so TweenService cannot drive it \u2014 this steps the\\nscale manually on [RunService.Heartbeat] while still borrowing TweenService\'s\\neasing curves.\\n\\nConcurrency is handled with a `ScalingId` attribute on the model: starting a new\\ntween overwrites the id, and the previous tween notices and bows out. So calling\\nthis while the model is already scaling stops the previous tween and starts a new\\none rather than having the two fight.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":21,"path":"src/Shared/Class/ScaleTween.luau"}}')}}]);